-- Settlement events use their own open accounting period. Original requests stay immutable.
DROP TRIGGER workplace_expense_closed_update;
CREATE TRIGGER workplace_expense_closed_update BEFORE UPDATE ON workplace_requests WHEN NEW.kind='expense' AND NOT (OLD.status IN ('approved','complete') AND NEW.status IN ('approved','complete') AND NEW.business_date=OLD.business_date AND NEW.data_json=OLD.data_json AND NEW.user_id=OLD.user_id AND NEW.unit_id=OLD.unit_id AND NEW.manager_actor IS OLD.manager_actor AND NEW.reviewer_actor IS OLD.reviewer_actor) AND EXISTS(SELECT 1 FROM finance_period_events p WHERE p.status='closed' AND p.revision=(SELECT MAX(x.revision) FROM finance_period_events x WHERE x.month=p.month) AND (substr(NEW.business_date,1,7)<=p.month OR substr(json_extract(NEW.data_json,'$.settlementDate'),1,7)<=p.month)) BEGIN SELECT RAISE(ABORT,'closed finance workplace request'); END;
DROP TRIGGER workplace_payment_links_closed;
CREATE TRIGGER workplace_payment_links_closed BEFORE INSERT ON workplace_payment_links WHEN EXISTS(SELECT 1 FROM workplace_requests r JOIN finance_period_events p ON p.status='closed' AND p.revision=(SELECT MAX(x.revision) FROM finance_period_events x WHERE x.month=p.month) WHERE r.id=NEW.request_id AND (SELECT substr(d.business_date,1,7) FROM finance_documents d WHERE d.id=NEW.document_id)<=p.month) BEGIN SELECT RAISE(ABORT,'closed finance workplace evidence'); END;
DROP TRIGGER workplace_proofs_closed;
CREATE TRIGGER workplace_proofs_closed BEFORE INSERT ON workplace_proofs WHEN EXISTS(SELECT 1 FROM workplace_requests r JOIN finance_period_events p ON p.status='closed' AND p.revision=(SELECT MAX(x.revision) FROM finance_period_events x WHERE x.month=p.month) WHERE r.id=NEW.request_id AND r.status NOT IN ('approved','complete') AND (substr(r.business_date,1,7)<=p.month OR substr(json_extract(r.data_json,'$.settlementDate'),1,7)<=p.month)) BEGIN SELECT RAISE(ABORT,'closed finance workplace evidence'); END;

-- Correction re-entry has its own record; no old bank reference is erased or renamed.
CREATE TABLE workplace_payment_reentries (id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES workplace_requests(id), document_id TEXT NOT NULL UNIQUE REFERENCES finance_documents(id), proof_id TEXT NOT NULL UNIQUE REFERENCES workplace_proofs(id), bank_account TEXT NOT NULL, bank_reference TEXT NOT NULL, bank_date TEXT NOT NULL, legal_entity TEXT NOT NULL);
CREATE TABLE workplace_reentry_checks (id TEXT PRIMARY KEY, link_id TEXT NOT NULL UNIQUE REFERENCES workplace_payment_reentries(id), allocation_id TEXT NOT NULL UNIQUE REFERENCES finance_documents(id), actor_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE VIEW workplace_all_payments AS SELECT * FROM workplace_payment_links UNION ALL SELECT * FROM workplace_payment_reentries;
CREATE VIEW workplace_all_checks AS SELECT * FROM workplace_bank_checks UNION ALL SELECT * FROM workplace_reentry_checks;
CREATE TABLE finance_access_modes (user_id TEXT PRIMARY KEY REFERENCES users(id), mode TEXT NOT NULL CHECK(mode IN ('headquarters','scoped')), actor_id TEXT NOT NULL REFERENCES users(id), reason TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TRIGGER workplace_payment_reentries_clock_insert AFTER INSERT ON workplace_payment_reentries BEGIN UPDATE workplace_clock SET version=version+1 WHERE id='global'; INSERT INTO finance_clock VALUES('global',1) ON CONFLICT(id) DO UPDATE SET version=version+1; END;
CREATE TRIGGER workplace_payment_reentries_maintenance_insert BEFORE INSERT ON workplace_payment_reentries WHEN EXISTS(SELECT 1 FROM system_maintenance WHERE id='global' AND mode<>'normal' AND expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')) BEGIN SELECT RAISE(ABORT,'guard_maintenance'); END;
CREATE TRIGGER workplace_payment_reentries_clock_update AFTER UPDATE ON workplace_payment_reentries BEGIN UPDATE workplace_clock SET version=version+1 WHERE id='global'; INSERT INTO finance_clock VALUES('global',1) ON CONFLICT(id) DO UPDATE SET version=version+1; END;
CREATE TRIGGER workplace_payment_reentries_maintenance_update BEFORE UPDATE ON workplace_payment_reentries WHEN EXISTS(SELECT 1 FROM system_maintenance WHERE id='global' AND mode<>'normal' AND expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')) BEGIN SELECT RAISE(ABORT,'guard_maintenance'); END;
CREATE TRIGGER workplace_payment_reentries_immutable_update BEFORE UPDATE ON workplace_payment_reentries BEGIN SELECT RAISE(ABORT,'immutable workplace evidence'); END;
CREATE TRIGGER workplace_payment_reentries_clock_delete AFTER DELETE ON workplace_payment_reentries BEGIN UPDATE workplace_clock SET version=version+1 WHERE id='global'; INSERT INTO finance_clock VALUES('global',1) ON CONFLICT(id) DO UPDATE SET version=version+1; END;
CREATE TRIGGER workplace_payment_reentries_maintenance_delete BEFORE DELETE ON workplace_payment_reentries WHEN EXISTS(SELECT 1 FROM system_maintenance WHERE id='global' AND mode<>'normal' AND expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')) BEGIN SELECT RAISE(ABORT,'guard_maintenance'); END;
CREATE TRIGGER workplace_payment_reentries_immutable_delete BEFORE DELETE ON workplace_payment_reentries BEGIN SELECT RAISE(ABORT,'immutable workplace evidence'); END;
CREATE TRIGGER workplace_reentry_checks_clock_insert AFTER INSERT ON workplace_reentry_checks BEGIN UPDATE workplace_clock SET version=version+1 WHERE id='global'; INSERT INTO finance_clock VALUES('global',1) ON CONFLICT(id) DO UPDATE SET version=version+1; END;
CREATE TRIGGER workplace_reentry_checks_maintenance_insert BEFORE INSERT ON workplace_reentry_checks WHEN EXISTS(SELECT 1 FROM system_maintenance WHERE id='global' AND mode<>'normal' AND expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')) BEGIN SELECT RAISE(ABORT,'guard_maintenance'); END;
