CREATE TRIGGER workplace_reentry_checks_immutable_update BEFORE UPDATE ON workplace_reentry_checks BEGIN SELECT RAISE(ABORT,'immutable workplace evidence'); END;
CREATE TRIGGER workplace_reentry_checks_clock_delete AFTER DELETE ON workplace_reentry_checks BEGIN UPDATE workplace_clock SET version=version+1 WHERE id='global'; INSERT INTO finance_clock VALUES('global',1) ON CONFLICT(id) DO UPDATE SET version=version+1; END;
CREATE TRIGGER workplace_reentry_checks_maintenance_delete BEFORE DELETE ON workplace_reentry_checks WHEN EXISTS(SELECT 1 FROM system_maintenance WHERE id='global' AND mode<>'normal' AND expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')) BEGIN SELECT RAISE(ABORT,'guard_maintenance'); END;
CREATE TRIGGER workplace_reentry_checks_immutable_delete BEFORE DELETE ON workplace_reentry_checks BEGIN SELECT RAISE(ABORT,'immutable workplace evidence'); END;
CREATE TRIGGER finance_access_modes_clock_insert AFTER INSERT ON finance_access_modes BEGIN UPDATE workplace_clock SET version=version+1 WHERE id='global'; INSERT INTO finance_clock VALUES('global',1) ON CONFLICT(id) DO UPDATE SET version=version+1; END;
CREATE TRIGGER finance_access_modes_maintenance_insert BEFORE INSERT ON finance_access_modes WHEN EXISTS(SELECT 1 FROM system_maintenance WHERE id='global' AND mode<>'normal' AND expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')) BEGIN SELECT RAISE(ABORT,'guard_maintenance'); END;
