CREATE TRIGGER finance_access_modes_clock_delete AFTER DELETE ON finance_access_modes BEGIN UPDATE workplace_clock SET version=version+1 WHERE id='global'; INSERT INTO finance_clock VALUES('global',1) ON CONFLICT(id) DO UPDATE SET version=version+1; END;
