CREATE TRIGGER workplace_reentries_closed BEFORE INSERT ON workplace_payment_reentries WHEN EXISTS(SELECT 1 FROM finance_period_events p WHERE p.status='closed' AND p.revision=(SELECT MAX(x.revision) FROM finance_period_events x WHERE x.month=p.month) AND (SELECT substr(d.business_date,1,7) FROM finance_documents d WHERE d.id=NEW.document_id)<=p.month) BEGIN SELECT RAISE(ABORT,'closed finance workplace evidence'); END;

CREATE TABLE workplace_request_cancellations (request_id TEXT PRIMARY KEY REFERENCES workplace_requests(id), business_date TEXT NOT NULL, reason TEXT NOT NULL, requester_id TEXT NOT NULL REFERENCES users(id), reviewer_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, CHECK(requester_id<>reviewer_id));
CREATE TRIGGER workplace_cancellations_maintenance_insert BEFORE INSERT ON workplace_request_cancellations WHEN EXISTS(SELECT 1 FROM system_maintenance WHERE id='global' AND mode<>'normal' AND expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')) BEGIN SELECT RAISE(ABORT,'guard_maintenance'); END;
CREATE TRIGGER workplace_cancellations_clock_insert AFTER INSERT ON workplace_request_cancellations BEGIN UPDATE workplace_clock SET version=version+1 WHERE id='global'; INSERT INTO finance_clock VALUES('global',1) ON CONFLICT(id) DO UPDATE SET version=version+1; END;
CREATE TRIGGER workplace_cancellations_maintenance_update BEFORE UPDATE ON workplace_request_cancellations WHEN EXISTS(SELECT 1 FROM system_maintenance WHERE id='global' AND mode<>'normal' AND expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')) BEGIN SELECT RAISE(ABORT,'guard_maintenance'); END;
CREATE TRIGGER workplace_cancellations_clock_update AFTER UPDATE ON workplace_request_cancellations BEGIN UPDATE workplace_clock SET version=version+1 WHERE id='global'; INSERT INTO finance_clock VALUES('global',1) ON CONFLICT(id) DO UPDATE SET version=version+1; END;
CREATE TRIGGER workplace_cancellations_immutable_update BEFORE UPDATE ON workplace_request_cancellations BEGIN SELECT RAISE(ABORT,'immutable workplace evidence'); END;
CREATE TRIGGER workplace_cancellations_maintenance_delete BEFORE DELETE ON workplace_request_cancellations WHEN EXISTS(SELECT 1 FROM system_maintenance WHERE id='global' AND mode<>'normal' AND expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')) BEGIN SELECT RAISE(ABORT,'guard_maintenance'); END;
CREATE TRIGGER workplace_cancellations_clock_delete AFTER DELETE ON workplace_request_cancellations BEGIN UPDATE workplace_clock SET version=version+1 WHERE id='global'; INSERT INTO finance_clock VALUES('global',1) ON CONFLICT(id) DO UPDATE SET version=version+1; END;
CREATE TRIGGER workplace_cancellations_immutable_delete BEFORE DELETE ON workplace_request_cancellations BEGIN SELECT RAISE(ABORT,'immutable workplace evidence'); END;
CREATE TRIGGER workplace_cancellations_closed BEFORE INSERT ON workplace_request_cancellations WHEN EXISTS(SELECT 1 FROM finance_period_events p WHERE p.status='closed' AND p.revision=(SELECT MAX(x.revision) FROM finance_period_events x WHERE x.month=p.month) AND substr(NEW.business_date,1,7)<=p.month) BEGIN SELECT RAISE(ABORT,'closed finance workplace evidence'); END;

CREATE TABLE finance_ad_statements (id TEXT PRIMARY KEY, budget_id TEXT NOT NULL REFERENCES workplace_requests(id), unit_id TEXT NOT NULL REFERENCES workplace_units(id), from_day TEXT NOT NULL, to_day TEXT NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','reviewed','rejected')), data_json TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, reviewer_id TEXT REFERENCES users(id), review_note TEXT, reviewed_at TEXT);
CREATE TRIGGER finance_ad_statements_no_delete BEFORE DELETE ON finance_ad_statements BEGIN SELECT RAISE(ABORT,'immutable finance source'); END;
CREATE TRIGGER finance_ad_statements_review_only BEFORE UPDATE ON finance_ad_statements WHEN (OLD.status<>'pending' AND NOT(OLD.status='reviewed' AND NEW.status='rejected')) OR NEW.status NOT IN ('reviewed','rejected') OR NEW.data_json<>OLD.data_json OR NEW.budget_id<>OLD.budget_id OR NEW.unit_id<>OLD.unit_id OR NEW.from_day<>OLD.from_day OR NEW.to_day<>OLD.to_day OR NEW.actor_id<>OLD.actor_id OR NEW.reviewer_id=OLD.actor_id BEGIN SELECT RAISE(ABORT,'immutable finance source'); END;
CREATE TRIGGER finance_ad_statements_clock_insert AFTER INSERT ON finance_ad_statements BEGIN INSERT INTO finance_clock VALUES('global',1) ON CONFLICT(id) DO UPDATE SET version=version+1; END;
CREATE TRIGGER finance_ad_statements_maintenance_insert BEFORE INSERT ON finance_ad_statements WHEN EXISTS(SELECT 1 FROM system_maintenance WHERE id='global' AND mode<>'normal' AND expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')) BEGIN SELECT RAISE(ABORT,'guard_maintenance'); END;
CREATE TRIGGER finance_ad_statements_closed_insert BEFORE INSERT ON finance_ad_statements WHEN EXISTS(SELECT 1 FROM finance_period_events p WHERE p.status='closed' AND p.revision=(SELECT MAX(x.revision) FROM finance_period_events x WHERE x.month=p.month) AND substr(NEW.to_day,1,7)<=p.month) BEGIN SELECT RAISE(ABORT,'closed finance evidence'); END;
CREATE TRIGGER finance_ad_statements_clock_update AFTER UPDATE ON finance_ad_statements BEGIN INSERT INTO finance_clock VALUES('global',1) ON CONFLICT(id) DO UPDATE SET version=version+1; END;
CREATE TRIGGER finance_ad_statements_maintenance_update BEFORE UPDATE ON finance_ad_statements WHEN EXISTS(SELECT 1 FROM system_maintenance WHERE id='global' AND mode<>'normal' AND expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')) BEGIN SELECT RAISE(ABORT,'guard_maintenance'); END;
CREATE TRIGGER finance_ad_statements_closed_update BEFORE UPDATE ON finance_ad_statements WHEN EXISTS(SELECT 1 FROM finance_period_events p WHERE p.status='closed' AND p.revision=(SELECT MAX(x.revision) FROM finance_period_events x WHERE x.month=p.month) AND substr(NEW.to_day,1,7)<=p.month) BEGIN SELECT RAISE(ABORT,'closed finance evidence'); END;

CREATE TABLE hr_finance_handoffs (id TEXT PRIMARY KEY, unit_id TEXT NOT NULL REFERENCES workplace_units(id), month TEXT NOT NULL, version INTEGER NOT NULL, snapshot_json TEXT NOT NULL, fingerprint TEXT NOT NULL, reason TEXT NOT NULL, issued_by TEXT NOT NULL REFERENCES users(id), issued_at TEXT NOT NULL, legal_entity TEXT NOT NULL, acknowledged_by TEXT REFERENCES users(id), acknowledged_at TEXT, UNIQUE(unit_id,month,version));
CREATE TRIGGER hr_handoff_no_delete BEFORE DELETE ON hr_finance_handoffs BEGIN SELECT RAISE(ABORT,'immutable HR handoff'); END;
CREATE TRIGGER hr_handoff_ack_only BEFORE UPDATE ON hr_finance_handoffs WHEN OLD.acknowledged_by IS NOT NULL OR NEW.snapshot_json<>OLD.snapshot_json OR NEW.fingerprint<>OLD.fingerprint OR NEW.month<>OLD.month OR NEW.unit_id<>OLD.unit_id OR NEW.issued_by<>OLD.issued_by OR NEW.version<>OLD.version OR NEW.acknowledged_by IS NULL OR NEW.acknowledged_by=OLD.issued_by BEGIN SELECT RAISE(ABORT,'immutable HR handoff'); END;
CREATE TRIGGER hr_handoff_clock_insert AFTER INSERT ON hr_finance_handoffs BEGIN UPDATE workplace_clock SET version=version+1 WHERE id='global'; END;
CREATE TRIGGER hr_handoff_maintenance_insert BEFORE INSERT ON hr_finance_handoffs WHEN EXISTS(SELECT 1 FROM system_maintenance WHERE id='global' AND mode<>'normal' AND expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')) BEGIN SELECT RAISE(ABORT,'guard_maintenance'); END;
CREATE TRIGGER hr_handoff_clock_update AFTER UPDATE ON hr_finance_handoffs BEGIN UPDATE workplace_clock SET version=version+1 WHERE id='global'; END;
CREATE TRIGGER hr_handoff_maintenance_update BEFORE UPDATE ON hr_finance_handoffs WHEN EXISTS(SELECT 1 FROM system_maintenance WHERE id='global' AND mode<>'normal' AND expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')) BEGIN SELECT RAISE(ABORT,'guard_maintenance'); END;

